    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.TaskEnsureResult}
    )
  end

  @doc """
  Get task activity metrics for an organization

  Returns task activity metrics scoped to org-owned tasks (org tenant, no
  narrower user/team/agent scope). `open` counts currently open or
  in-progress org tasks, `created` counts tasks inserted in the UTC-day
  window, and `completed` counts tasks whose `closed_at` falls in that window
  while still in a closed status. Hard-deleted tasks are absent from the
  projection and therefore omitted. The daily series is zero-filled across
  the requested window and includes reconstructed end-of-day `open` stock.

  Any organization member may read this count-only summary. Requests from
  callers without org access return 404 so organization existence is not
  disclosed.


  Successful response
  """
  @spec metrics(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksMetrics.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksMetrics.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def metrics(
        client,
        org,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksMetrics.Params{}
      ) do
    path = "/api/v1/orgs/#{ArchAstro.SDK.Path.encode(org)}/tasks/metrics"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksMetrics.Response}
    )
  end

  @doc """
  List an organization's ready tasks

  Returns open org-owned tasks with no unfinished blockers and no active
  session lease. Readiness is calculated by the server from the current task
  projection. It is a snapshot, not a reservation; claim a task lease before
  starting work.

  Results are ordered by priority (0, the most urgent, first), then oldest
  first, so the first page is always the most urgent ready work.

  Pass `explain=true` to include every open task with a stable readiness reason.


  Successful response
  """
  @spec ready(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksReady.Params.t()
        ) ::
