          | {:error, ArchAstro.SDK.Error.reason()}
  def ready(
        client,
        org,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksReady.Params{}
      ) do
    path = "/api/v1/orgs/#{ArchAstro.SDK.Path.encode(org)}/tasks/ready"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksReady.Response}
    )
  end

  @doc """
  Search an organization's tasks

  Performs a full-text search over org-owned tasks for the specified
  organization and returns matching results. Combine `q` with the optional
  filters to narrow the result set further. When no query is provided, the
  endpoint behaves like a filtered list.

  The `query` field in the response echoes the effective search query.
  Explicitly personal, team, or agent tasks are excluded here.


  Successful response
  """
  @spec search(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksSearch.Params.t()
