  def search(
        client,
        org,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksSearch.Params{}
      ) do
    path = "/api/v1/orgs/#{ArchAstro.SDK.Path.encode(org)}/tasks/search"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgTasksSearch.Response}
    )
  end
